file.content:
    seed: Optional[int] = None  # scheduler shuffle seed; recorded in the run manifest for reproducibility

    @model_validator(mode="after")
    def _apply_timeout_seconds(self) -> "ExecutionConfig":
        if self.timeout_seconds is not None:
            self.timeout_ms = self.timeout_seconds * 1000
        return self


class OutputConfig(BaseModel):
    store: Literal["sqlite", "postgres"] = "sqlite"
    db_path: str = ".retobs/results.db"
    postgres_dsn: Optional[str] = None  # or set via RETOBS_POSTGRES_DSN env var
    export: List[Literal["json", "csv"]] = []
    dashboard: bool = False


class ReleaseIdentityConfig(BaseModel):
    service_id: str | None = None
    deployment_revision: str | None = None
    corpus_revision: str | None = None
    index_build_id: str | None = None
    chunking_revision: str | None = None
    embedding_model_revision: str | None = None
    reranker_model_revision: str | None = None


class ExperimentConfig(BaseModel):
    experiment: ExperimentMeta
    dataset: DatasetConfig
    pipelines: List[PipelineConfig] = Field(default_factory=list)
    graphs: List[GraphPipelineConfig] = Field(default_factory=list)
    stages: Dict[str, StageConfig] = Field(default_factory=dict)
    combinations: Optional[CombinationConfig] = None
    labels: LabelsConfig = Field(default_factory=LabelsConfig)
    profiling: bool = True
    costs: Dict[str, Dict[str, float]] = Field(default_factory=dict)
    metrics: MetricsConfig = Field(default_factory=MetricsConfig)
    execution: ExecutionConfig = Field(default_factory=ExecutionConfig)
    output: OutputConfig = Field(default_factory=OutputConfig)
    release_identity: ReleaseIdentityConfig = Field(default_factory=ReleaseIdentityConfig)

    @model_validator(mode="after")
    def expand_combinations(self) -> "ExperimentConfig":
        if self.combinations and self.combinations.include:
            if not self.stages:
                raise ValueError("combinations requires a top-level stages mapping")
            seen_ids: set[str] = {p.id for p in self.pipelines}
            all_combos: list[list[str]] = []

            def add_if_new(sub: list[str]) -> None:
                pid = "__".join(sub)
                if pid not in seen_ids and sub not in all_combos:
                    all_combos.append(sub)
                    seen_ids.add(pid)

            ablations = self.combinations.ablations

            for combo in self.combinations.include:
                missing = [s for s in combo if s not in self.stages]
                if missing:
                    raise ValueError(f"Unknown stage id(s) in combinations: {missing}")

                if ablations is True:
                    # Full mode: all ordered subsequences starting with combo[0]
                    first, rest = combo[0], combo[1:]
                    for r in range(len(rest) + 1):
                        for indices in iter_combos(range(len(rest)), r):
                            add_if_new([first] + [rest[i] for i in indices])
                elif isinstance(ablations, list) and ablations:
                    # Targeted mode: all subsets of include/exclude for nominated stages
                    targeted_set = set(ablations)
                    targeted_in_combo = [s for s in combo[1:] if s in targeted_set]
                    if not targeted_in_combo:
                        add_if_new(combo)
                    else:
                        for r in range(len(targeted_in_combo) + 1):
                            for subset in iter_combos(range(len(targeted_in_combo)), r):
                                included = {targeted_in_combo[i] for i in subset}
                                sub = [combo[0]] + [
                                    s for s in combo[1:]
                                    if s not in targeted_set or s in included
                                ]
                                add_if_new(sub)
                else:
                    add_if_new(combo)

            expanded = [
                PipelineConfig(
                    id="__".join(combo),
                    stages=[self.stages[s].model_copy(deep=True) for s in combo],
                )
                for combo in all_combos
            ]
            self.pipelines = [*self.pipelines, *expanded]
        if not self.pipelines and not self.graphs:
            raise ValueError("At least one pipeline, combination, or graph is required")
        graph_ids = {g.id for g in self.graphs}
        pipeline_ids = {p.id for p in self.pipelines}
        clash = graph_ids & pipeline_ids
        if clash:
            raise ValueError(f"graph and pipeline share id(s): {sorted(clash)}")
        return self

    @classmethod
    def from_yaml(cls, path: str) -> "ExperimentConfig":
        with open(path) as f:
            data = yaml.safe_load(f)
        return cls.model_validate(data)

from __future__ import annotations

import hashlib
import json
import platform
import subprocess
import sys
from importlib import metadata
from pathlib import Path
from typing import Any, Dict, List


def detect_forge_dataset_id(cfg: Any) -> str | None:
    """Read forge_metadata.json adjacent to the dataset paths, if present."""
    ds = getattr(cfg, "dataset", None)
    if ds is None:
        return None
    seen: set[Path] = set()
    for attr in ("queries_path", "corpus_path", "qrels_path"):
        value = getattr(ds, attr, None)
        if not value:
            continue
        parent = Path(value).parent
        if parent in seen:
            continue
        seen.add(parent)
        meta_path = parent / "forge_metadata.json"
        if not meta_path.is_file():
            continue
        try:
            data = json.loads(meta_path.read_text(encoding="utf-8"))
            dataset_id = data.get("dataset_id")
            if dataset_id:
                return str(dataset_id)
        except (OSError, json.JSONDecodeError, TypeError):
            continue
    return None


def build_run_manifest(
    config: Any,
    dataset_fingerprint: Dict[str, Any],
    latency_budget_ms: int | None = None,
    forge_dataset_id: str | None = None,
    golden_set: str | None = None,
    seed: int | None = None,
) -> Dict[str, Any]:
    """Capture enough environment detail to make a run auditable."""
    normalized_config = config.model_dump(mode="json") if hasattr(config, "model_dump") else config
    config_json = json.dumps(normalized_config, sort_keys=True, separators=(",", ":"), default=str)
    packages = {}
    for name in ("retobs", "numpy", "pydantic", "httpx", "rank-bm25", "sentence-transformers", "faiss-cpu"):
        try:
            packages[name] = metadata.version(name)
        except metadata.PackageNotFoundError:
            continue

    display = build_pipeline_display(config)
    manifest = {
        "schema_version": 3,
        "config_hash": hashlib.sha256(config_json.encode("utf-8")).hexdigest(),
        "normalized_config": normalized_config,
        "dataset": dataset_fingerprint,
        "python": sys.version,
        "platform": platform.platform(),
        "machine": platform.machine(),
        "packages": packages,
        "git_commit": _git_commit(),
        "git_dirty": _git_dirty(),
        "cache_results": getattr(getattr(config, "execution", None), "cache_results", None),
        "seed": seed if seed is not None else getattr(getattr(config, "execution", None), "seed", None),
        "execution": _execution_manifest(config, seed),
        "labeling": _label_manifest(config),
        "models": _model_inventory(config),
        "release_identity": _release_identity_manifest(config),
        "environment": {
            "python": sys.version,
            "platform": platform.platform(),
            "machine": platform.machine(),
            "processor": platform.processor() or None,
        },
        "counts": {
            "attempted": None,
            "completed": None,
            "labeled": None,
            "metric_eligible": None,
        },
        **display,
    }
    if latency_budget_ms is not None:
        manifest["latency_budget_ms"] = latency_budget_ms
    if forge_dataset_id is not None:
        manifest["forge_dataset_id"] = forge_dataset_id
    if golden_set is not None:
        manifest["golden_set"] = golden_set
    return manifest


def _release_identity_manifest(config: Any) -> Dict[str, Any]:
    identity = getattr(config, "release_identity", None)
    if identity is None:
        return {}
    if hasattr(identity, "model_dump"):
        return identity.model_dump(mode="json")
    return dict(identity)


def _stage_label(stage: Any) -> str:
    rid = getattr(stage, "retriever_id", None)
    if rid:
        return str(rid)
    stype = getattr(stage, "type", "") or ""
    return stype.replace("adapter.", "")


def build_pipeline_display(config: Any) -> Dict[str, Any]:
    """Per-pipeline stage labels and explicit ablation duplicate-stage hints from resolved config."""
    stage_labels: Dict[str, List[str]] = {}
    duplicate_ablation_stages: List[Dict[str, Any]] = []
    all_ids: set[str] = set()

    for pipeline in getattr(config, "pipelines", []) or []:
        all_ids.add(pipeline.id)
        stage_labels[pipeline.id] = [_stage_label(s) for s in pipeline.stages]

    for graph in getattr(config, "graphs", []) or []:
        all_ids.add(graph.id)
        stage_labels[graph.id] = [n.id for n in graph.nodes]

    for pid in sorted(stage_labels.keys(), key=len):
        parts = pid.split("__")
        for stage_index in range(len(parts) - 1):
            prefix = "__".join(parts[: stage_index + 1])
            if prefix in all_ids and prefix != pid:
                duplicate_ablation_stages.append(
                    {
                        "pipeline_id": pid,
                        "stage_index": stage_index,
                        "equivalent_pipeline_id": prefix,
                    }
                )

    return {
        "stage_labels": stage_labels,
        "duplicate_ablation_stages": duplicate_ablation_stages,
    }


def _git_commit() -> str | None:
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            check=True,
            capture_output=True,
            text=True,
            timeout=2,
        )
        return result.stdout.strip()
    except Exception:
        return None


def _git_dirty() -> bool | None:
    try:
        result = subprocess.run(
            ["git", "status", "--porcelain"],
            check=True,
            capture_output=True,
            text=True,
            timeout=2,
        )
        return bool(result.stdout.strip())
    except Exception:
        return None


def _execution_manifest(config: Any, seed: int | None) -> Dict[str, Any]:
    execution = getattr(config, "execution", None)
    configured_seed = seed if seed is not None else getattr(execution, "seed", None)
    return {
        "concurrency": getattr(execution, "concurrency", None),
        "timeout_ms": getattr(execution, "timeout_ms", None),
        "retry_attempts": getattr(execution, "retry_attempts", None),
        "cache_results": getattr(execution, "cache_results", None),
        "seed": configured_seed,
        "nondeterminism_flags": ["scheduler_seed_missing"] if configured_seed is None else [],
        "observed": {
            "cache_hits": None,
            "cache_misses": None,
            "timeouts": None,
            "retries": None,
        },
    }


def _label_manifest(config: Any) -> Dict[str, Any]:
    labels = getattr(config, "labels", None)
    return {
        "method": getattr(labels, "mode", None),
        "judge": getattr(labels, "judge", None),
        "model": getattr(labels, "model", None),
        "version": None,
    }


def _model_inventory(config: Any) -> List[Dict[str, Any]]:
    inventory: List[Dict[str, Any]] = []
    for pipeline in getattr(config, "pipelines", []) or []:
        for index, stage in enumerate(pipeline.stages):
            inventory.append({
                "pipeline_id": pipeline.id,
                "operator_id": getattr(stage, "retriever_id", None) or f"stage-{index}",
                "type": getattr(stage, "type", None),
                "model": getattr(stage, "model", None),
                "version": (getattr(stage, "config", None) or {}).get("model_version"),
            })
    for graph in getattr(config, "graphs", []) or []:
        for node in graph.nodes:
            inventory.append({
                "pipeline_id": graph.id,
                "operator_id": node.id,
                "type": node.type or node.op,
                "model": node.model,
                "version": node.config.get("model_version"),
            })
    return inventory

from __future__ import annotations

from dataclasses import dataclass, field, replace
from typing import Literal, Mapping

from retrieval_observatory.tracing.lineage_contract import LineageEvidence
from retrieval_observatory.tracing.model import Candidate, OperatorSpan, RetrievalTrace

OutcomeKind = Literal[
    "relevant_retained",
    "irrelevant_removed",
    "irrelevant_retained",
    "relevant_lost_upstream",
    "relevant_dropped_at_stage",
    "unknown_relevance",
    "lineage_incomplete",
]

_EVIDENCE_RANK = {"recorded": 0, "legacy_inferred": 1, "partial": 2, "unavailable": 3}


@dataclass(frozen=True)
class CandidateSource:
    document_id: str | None
    document_revision: str | None
    content_hash: str | None
    char_start: int | None
    char_end: int | None
    preview: str | None


@dataclass(frozen=True)
class CandidateStage:
    op_id: str
    op_type: str
    branch_id: str | None
    rank: int
    score: float
    score_components: Mapping[str, float]
    input_rank: int | None = None
    output_rank: int | None = None
    score_type: str | None = None
    score_model: str | None = None


@dataclass(frozen=True)
class CandidateRoute:
    candidate_ids: tuple[str, ...]
    operator_ids: tuple[str, ...]
    branch_ids: tuple[str, ...]
    stages: tuple[CandidateStage, ...]
    lineage_evidence: LineageEvidence


@dataclass(frozen=True)
class RelevanceEvidence:
    kind: Literal["relevant", "irrelevant", "unknown"]
    grade: int | None = None
    evidence: Literal["validated", "unavailable"] = "unavailable"


@dataclass(frozen=True)
class CandidateOutcome:
    kind: OutcomeKind
    evidence: LineageEvidence
    operator_id: str | None = None
    branch_id: str | None = None
    reason: str | None = None


@dataclass(frozen=True)
class CandidatePassport:
    candidate_id: str
    logical_chunk_id: str | None
    source: CandidateSource
    parent_candidate_ids: tuple[str, ...]
    routes: tuple[CandidateRoute, ...]
    relevance: RelevanceEvidence
    outcome: CandidateOutcome
    lineage_evidence: LineageEvidence
    final_context_member: bool = False
    removed_at: str | None = None
    removal_branch_id: str | None = None
    removal_reason: str | None = None
    removal_evidence: LineageEvidence = "unavailable"
    derived_child_ids: tuple[str, ...] = ()


@dataclass(frozen=True)
class CandidateLineageEdge:
    source_candidate_id: str
    target_candidate_id: str
    op_id: str
    evidence: LineageEvidence


@dataclass(frozen=True)
class CandidateLineageGraph:
    trace_id: str
    run_id: str | None
    query_id: str
    pipeline_id: str
    topology_hash: str
    candidates: Mapping[str, CandidatePassport]
    edges: tuple[CandidateLineageEdge, ...]
    qrels_for_query: Mapping[str, int] = field(default_factory=dict)
    qrel_chunk_mapping_complete: bool = False
    retrieval_entry_complete: bool = False
    observed_logical_chunk_ids: tuple[str, ...] = ()


def _worst_evidence(*values: LineageEvidence) -> LineageEvidence:
    return max(values, key=_EVIDENCE_RANK.__getitem__)


def _preview(candidate: Candidate, trace: RetrievalTrace) -> str | None:
    if trace.capture.redacted_field_count or trace.capture.omitted_field_count:
        return None
    for key in ("preview", "text", "title", "snippet"):
        value = candidate.metadata.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return None


def _branch(span: OperatorSpan) -> str | None:
    value = span.branch_id if span.branch_id is not None else span.params.get("branch_id")
    return str(value) if value is not None else None


def _relevance(candidate: Candidate, qrels_for_query: Mapping[str, int]) -> RelevanceEvidence:
    logical_chunk_id = candidate.logical_chunk_id
    if (
        candidate.identity_evidence != "recorded"
        or logical_chunk_id is None
        or logical_chunk_id not in qrels_for_query
    ):
        return RelevanceEvidence("unknown")
    grade = int(qrels_for_query[logical_chunk_id])
    return RelevanceEvidence(
        "relevant" if grade > 0 else "irrelevant",
        grade=grade,
        evidence="validated",
    )


def classify_candidate_outcome(passport: CandidatePassport) -> CandidateOutcome:
    if passport.final_context_member:
        if passport.relevance.kind == "relevant":
            return CandidateOutcome("relevant_retained", passport.lineage_evidence)
        if passport.relevance.kind == "irrelevant":
            return CandidateOutcome("irrelevant_retained", passport.lineage_evidence)
        return CandidateOutcome("unknown_relevance", passport.lineage_evidence)

    if passport.removed_at is not None and passport.removal_evidence in {
        "recorded",
        "legacy_inferred",
    }:
        if passport.relevance.kind == "unknown":
            return CandidateOutcome(
                "unknown_relevance",
                passport.removal_evidence,
                operator_id=passport.removed_at,
                branch_id=passport.removal_branch_id,
                reason=passport.removal_reason,
            )
        return CandidateOutcome(
            "relevant_dropped_at_stage"
            if passport.relevance.kind == "relevant"
            else "irrelevant_removed",
            passport.removal_evidence,
            operator_id=passport.removed_at,
            branch_id=passport.removal_branch_id,
            reason=passport.removal_reason,
        )
    return CandidateOutcome(
        "lineage_incomplete",
        "partial" if passport.lineage_evidence != "unavailable" else "unavailable",
        operator_id=passport.removed_at,
        branch_id=passport.removal_branch_id,
        reason="candidate exit or final membership is not fully observed",
    )


def _query_qrels(
    trace: RetrievalTrace,
    qrels_for_query: Mapping[str, int] | None,
    qrels: Mapping[str, Mapping[str, int]] | None,
) -> Mapping[str, int]:
    if qrels_for_query is not None:
        return dict(qrels_for_query)
    if qrels is not None:
        return dict(qrels.get(trace.query_id, {}))
    return {}


def build_candidate_lineage(
    trace: RetrievalTrace,
    *,
    qrels_for_query: Mapping[str, int] | None = None,
    qrel_chunk_mapping_complete: bool = False,
    retrieval_entry_complete: bool | None = None,
    qrels: Mapping[str, Mapping[str, int]] | None = None,
) -> CandidateLineageGraph:
    query_qrels = _query_qrels(trace, qrels_for_query, qrels)
    occurrences: dict[str, list[tuple[OperatorSpan, Candidate, str]]] = {}
    parents: dict[str, list[str]] = {}
    children: dict[str, list[str]] = {}
    edges: list[CandidateLineageEdge] = []

    for span in trace.spans:
        for candidates in span.input_groups.values():
            for candidate in candidates:
                occurrences.setdefault(candidate.candidate_id, []).append((span, candidate, "input"))
        for candidate in span.outputs:
            occurrences.setdefault(candidate.candidate_id, []).append((span, candidate, "output"))
            for parent_id in candidate.parent_candidate_ids:
                if parent_id == candidate.candidate_id:
                    continue
                parents.setdefault(candidate.candidate_id, []).append(parent_id)
                children.setdefault(parent_id, []).append(candidate.candidate_id)
                edges.append(
                    CandidateLineageEdge(
                        parent_id,
                        candidate.candidate_id,
                        span.op_id,
                        candidate.identity_evidence,
                    )
                )

    final_ids = {
        candidate.candidate_id
        for span in trace.spans
        if span.op_id in trace.final_op_ids
        for candidate in span.outputs
    }
    trace_partial = bool(
        trace.capture.lineage_evidence in {"partial", "unavailable"}
        or trace.capture.candidates_truncated
        or trace.capture.omitted_field_count
    )
    span_index = {span.op_id: index for index, span in enumerate(trace.spans)}

    def reaches_final(candidate_id: str, visiting: frozenset[str] = frozenset()) -> bool:
        if candidate_id in final_ids:
            return True
        if candidate_id in visiting:
            return False
        return any(
            reaches_final(child_id, visiting | {candidate_id})
            for child_id in children.get(candidate_id, ())
        )

    def routes(candidate_id: str, visiting: frozenset[str] = frozenset()) -> tuple[CandidateRoute, ...]:
        if candidate_id in visiting:
            return ()
        output_occurrences = [
            item for item in occurrences.get(candidate_id, ()) if item[2] == "output"
        ]
        stages = tuple(
            CandidateStage(
                span.op_id,
                str(span.op_type),
                _branch(span),
                candidate.output_rank if candidate.output_rank is not None else candidate.rank,
                candidate.score,
                dict(candidate.score_components),
                candidate.input_rank,
                candidate.output_rank if candidate.output_rank is not None else candidate.rank,
                candidate.score_type,
                candidate.score_model,
            )
            for span, candidate, _ in sorted(
                output_occurrences, key=lambda item: span_index[item[0].op_id]
            )
        )
        evidence: LineageEvidence = "recorded"
        for _, candidate, _ in output_occurrences:
            evidence = _worst_evidence(evidence, candidate.identity_evidence)
        if trace_partial:
            evidence = _worst_evidence(evidence, "partial")
        parent_ids = tuple(dict.fromkeys(parents.get(candidate_id, ())))
        if not parent_ids:
            return (
                CandidateRoute(
                    (candidate_id,),
                    tuple(stage.op_id for stage in stages),
                    tuple(stage.branch_id for stage in stages if stage.branch_id is not None),
                    stages,
                    evidence,
                ),
            )
        result = []
        for parent_id in parent_ids:
            parent_routes = routes(parent_id, visiting | {candidate_id}) or (
                CandidateRoute((parent_id,), (), (), (), "partial"),
            )
            for parent_route in parent_routes:
                result.append(
                    CandidateRoute(
                        (*parent_route.candidate_ids, candidate_id),
                        tuple(dict.fromkeys((*parent_route.operator_ids, *(stage.op_id for stage in stages)))),
                        tuple(dict.fromkeys((*parent_route.branch_ids, *(stage.branch_id for stage in stages if stage.branch_id)))),
                        (*parent_route.stages, *stages),
                        _worst_evidence(parent_route.lineage_evidence, evidence),
                    )
                )
        return tuple(result)

    passports: dict[str, CandidatePassport] = {}
    for candidate_id, items in occurrences.items():
        ordered = sorted(items, key=lambda item: span_index[item[0].op_id])
        candidate = next((item[1] for item in ordered if item[2] == "output"), ordered[0][1])
        lineage_evidence = candidate.identity_evidence
        if trace_partial:
            lineage_evidence = _worst_evidence(lineage_evidence, "partial")

        removed_at = None
        removal_branch_id = None
        removal_reason = None
        removal_evidence: LineageEvidence = "unavailable"
        for span, input_candidate, location in ordered:
            if location != "input":
                continue
            output_ids = {output.candidate_id for output in span.outputs}
            transitioned_ids = {
                parent_id for output in span.outputs for parent_id in output.parent_candidate_ids
            }
            if candidate_id in output_ids or candidate_id in transitioned_ids:
                continue
            removed_at = span.op_id
            removal_branch_id = _branch(span)
            removal_reason = input_candidate.decision_reason or input_candidate.drop_reason
            removal_evidence = input_candidate.decision_evidence
            if removal_evidence == "unavailable" and not trace_partial:
                removal_evidence = "legacy_inferred"
                removal_reason = removal_reason or "candidate absent from recorded operator output"
            if removal_evidence not in {"recorded", "legacy_inferred"}:
                lineage_evidence = _worst_evidence(lineage_evidence, "partial")
            break

        route_values = routes(candidate_id)
        for route in route_values:
            lineage_evidence = _worst_evidence(lineage_evidence, route.lineage_evidence)
        passport = CandidatePassport(
            candidate_id=candidate_id,
            logical_chunk_id=candidate.logical_chunk_id,
            source=CandidateSource(
                candidate.document_id
                or (candidate.doc_id if candidate.identity_evidence == "recorded" else None),
                candidate.document_revision,
                candidate.content_hash,
                candidate.char_start,
                candidate.char_end,
                _preview(candidate, trace),
            ),
            parent_candidate_ids=tuple(dict.fromkeys(parents.get(candidate_id, ()))),
            routes=route_values,
            relevance=_relevance(candidate, query_qrels),
            outcome=CandidateOutcome("lineage_incomplete", "unavailable"),
            lineage_evidence=lineage_evidence,
            final_context_member=reaches_final(candidate_id),
            removed_at=removed_at,
            removal_branch_id=removal_branch_id,
            removal_reason=removal_reason,
            removal_evidence=removal_evidence,
            derived_child_ids=tuple(dict.fromkeys(children.get(candidate_id, ()))),
        )
        passports[candidate_id] = replace(passport, outcome=classify_candidate_outcome(passport))

    source_spans = [span for span in trace.spans if span.op_type == "SOURCE"]
    if retrieval_entry_complete is None:
        retrieval_entry_complete = bool(source_spans) and not trace_partial
    return CandidateLineageGraph(
        trace_id=trace.trace_id,
        run_id=trace.run_id,
        query_id=trace.query_id,
        pipeline_id=trace.pipeline_id,
        topology_hash=trace.topology_hash(),
        candidates=passports,
        edges=tuple(dict.fromkeys(edges)),
        qrels_for_query=query_qrels,
        qrel_chunk_mapping_complete=qrel_chunk_mapping_complete,
        retrieval_entry_complete=bool(retrieval_entry_complete),
        observed_logical_chunk_ids=tuple(
            sorted({item.logical_chunk_id for item in passports.values() if item.logical_chunk_id})
        ),
    )

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Mapping

from retrieval_observatory.tracing.lineage import CandidateLineageGraph, OutcomeKind

_OUTCOMES: tuple[OutcomeKind, ...] = (
    "relevant_retained",
    "irrelevant_removed",
    "irrelevant_retained",
    "relevant_lost_upstream",
    "relevant_dropped_at_stage",
    "unknown_relevance",
    "lineage_incomplete",
)


@dataclass(frozen=True)
class OutcomeCounts:
    relevant_retained: int = 0
    irrelevant_removed: int = 0
    irrelevant_retained: int = 0
    relevant_lost_upstream: int = 0
    relevant_dropped_at_stage: int = 0
    unknown_relevance: int = 0
    lineage_incomplete: int = 0


@dataclass(frozen=True)
class StageLossAccounting(OutcomeCounts):
    by_operator: Mapping[str, OutcomeCounts] = field(default_factory=dict)
    by_branch: Mapping[str, OutcomeCounts] = field(default_factory=dict)
    by_evidence: Mapping[str, OutcomeCounts] = field(default_factory=dict)
    unknown_relevance_count: int = 0
    incomplete_lineage_count: int = 0


def _counts(values: Mapping[str, int]) -> OutcomeCounts:
    return OutcomeCounts(**{outcome: int(values.get(outcome, 0)) for outcome in _OUTCOMES})


def _increment(group: dict[str, dict[str, int]], key: str, outcome: OutcomeKind) -> None:
    group.setdefault(key, {})[outcome] = group.setdefault(key, {}).get(outcome, 0) + 1


def build_stage_loss_accounting(graph: CandidateLineageGraph) -> StageLossAccounting:
    totals: dict[str, int] = {}
    by_operator: dict[str, dict[str, int]] = {}
    by_branch: dict[str, dict[str, int]] = {}
    by_evidence: dict[str, dict[str, int]] = {}

    for passport in graph.candidates.values():
        if passport.derived_child_ids:
            continue
        outcome = passport.outcome
        totals[outcome.kind] = totals.get(outcome.kind, 0) + 1
        operator_id = outcome.operator_id
        branch_id = outcome.branch_id
        if operator_id is None and passport.routes and passport.routes[0].stages:
            final_stage = passport.routes[0].stages[-1]
            operator_id = final_stage.op_id
            branch_id = final_stage.branch_id
        _increment(by_operator, operator_id or "unavailable", outcome.kind)
        _increment(by_branch, branch_id or "unassigned", outcome.kind)
        _increment(by_evidence, outcome.evidence, outcome.kind)

    unseen_relevant = {
        chunk_id
        for chunk_id, grade in graph.qrels_for_query.items()
        if int(grade) > 0 and chunk_id not in graph.observed_logical_chunk_ids
    }
    for _ in unseen_relevant:
        if graph.qrel_chunk_mapping_complete and graph.retrieval_entry_complete:
            outcome: OutcomeKind = "relevant_lost_upstream"
            evidence = "recorded"
        else:
            outcome = "lineage_incomplete"
            evidence = "partial"
        totals[outcome] = totals.get(outcome, 0) + 1
        _increment(by_operator, "retrieval_entry", outcome)
        _increment(by_branch, "unassigned", outcome)
        _increment(by_evidence, evidence, outcome)

    total_counts = _counts(totals)
    return StageLossAccounting(
        **total_counts.__dict__,
        by_operator={key: _counts(value) for key, value in sorted(by_operator.items())},
        by_branch={key: _counts(value) for key, value in sorted(by_branch.items())},
        by_evidence={key: _counts(value) for key, value in sorted(by_evidence.items())},
        unknown_relevance_count=total_counts.unknown_relevance,
        incomplete_lineage_count=total_counts.lineage_incomplete,
    )

from __future__ import annotations

import asyncio
from dataclasses import dataclass, field
from typing import Any, Literal, Mapping, Protocol, Sequence

from retrieval_observatory.config.operators import (
    FilterSpec,
    FuseSpec,
    GateSpec,
    OperatorSpec,
    RerankSpec,
    SourceSpec,
)
from retrieval_observatory.tracing.model import Candidate
from retrieval_observatory.types import Document, Query


class OperatorConfigurationError(ValueError):
    pass


@dataclass(frozen=True)
class ExecutionContext:
    query: Query
    adapters: Mapping[str, Any]

    def binding(self, name: str, op_type: str) -> Any:
        binding = self.adapters.get(name)
        if binding is None:
            raise OperatorConfigurationError(f"No {op_type} executor registered for {name}")
        return binding


@dataclass(frozen=True)
class OperatorExecutionResult:
    outputs: tuple[Any, ...]
    status: Literal["FIRED", "SKIPPED_BY_GATE", "ERROR", "TIMEOUT"] = "FIRED"
    gate_values: Mapping[str, object] = field(default_factory=dict)
    drop_reasons: Mapping[str, str] = field(default_factory=dict)
    metadata: Mapping[str, object] = field(default_factory=dict)


class OperatorExecutor(Protocol):
    async def execute(
        self,
        spec: OperatorSpec,
        input_groups: Mapping[str, tuple[Candidate, ...]],
        context: ExecutionContext,
    ) -> OperatorExecutionResult: ...


def _documents(candidates: Sequence[Candidate]) -> list[Document]:
    return [
        Document(
            id=item.doc_id,
            text=str(item.metadata.get("text", "")),
            score=item.score,
            rank=item.output_rank or item.rank,
            title=str(item.metadata.get("title", "")),
            metadata=dict(item.metadata),
        )
        for item in candidates
    ]


def _items(result: Any) -> tuple[Any, ...]:
    value = getattr(result, "documents", result)
    if value is None:
        return ()
    if isinstance(value, (list, tuple)):
        return tuple(value)
    return (value,)


async def _call(callable_: Any, *args: Any) -> Any:
    result = callable_(*args)
    return await result if asyncio.iscoroutine(result) else result


def _combined(input_groups: Mapping[str, tuple[Candidate, ...]]) -> tuple[Candidate, ...]:
    return tuple(candidate for candidates in input_groups.values() for candidate in candidates)


class SourceExecutor:
    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        assert isinstance(spec, SourceSpec)
        adapter = context.binding(spec.adapter, "SOURCE")
        fn = getattr(adapter, "retrieve", adapter)
        result = await _call(fn, context.query)
        return OperatorExecutionResult(_items(result))


class FuseExecutor:
    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        assert isinstance(spec, FuseSpec)
        if spec.method != "rrf":
            raise OperatorConfigurationError(f"Unsupported FUSE method {spec.method!r}")
        rrf_k = int(spec.params.get("rrf_k", 60))
        scores: dict[str, float] = {}
        rows: dict[str, Candidate] = {}
        for candidates in input_groups.values():
            for candidate in candidates:
                rank = candidate.output_rank or candidate.rank
                scores[candidate.doc_id] = scores.get(candidate.doc_id, 0.0) + 1.0 / (rrf_k + rank)
                rows.setdefault(candidate.doc_id, candidate)
        ranked = sorted(scores, key=lambda doc_id: (-scores[doc_id], doc_id))[: spec.top_k]
        return OperatorExecutionResult(
            tuple(
                Document(
                    id=doc_id,
                    text=str(rows[doc_id].metadata.get("text", "")),
                    score=scores[doc_id],
                    rank=index,
                    metadata=dict(rows[doc_id].metadata),
                )
                for index, doc_id in enumerate(ranked, 1)
            )
        )


class RerankExecutor:
    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        assert isinstance(spec, RerankSpec)
        adapter = context.binding(spec.adapter, "RERANK")
        combined = _combined(input_groups)
        fn = getattr(adapter, "rerank", adapter)
        result = await _call(fn, context.query, _documents(combined))
        return OperatorExecutionResult(_items(result)[: spec.top_k])


class NamedExecutor:
    field_name = ""
    op_type = ""

    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        name = getattr(spec, self.field_name)
        binding = context.binding(name, self.op_type)
        combined = _combined(input_groups)
        fn = getattr(binding, "execute", binding)
        result = await _call(fn, context.query, _documents(combined))
        return OperatorExecutionResult(_items(result))


class FilterExecutor(NamedExecutor):
    field_name, op_type = "predicate", "FILTER"

    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        assert isinstance(spec, FilterSpec)
        binding = context.binding(spec.predicate, "FILTER")
        combined = _combined(input_groups)
        documents = _documents(combined)
        fn = getattr(binding, "filter", binding)
        try:
            result = await _call(fn, context.query, documents)
            kept = _items(result)
        except TypeError:
            kept = tuple(doc for doc in documents if await _call(fn, doc))
        kept_ids = {str(getattr(item, "id", getattr(item, "doc_id", ""))) for item in kept}
        drops = {item.doc_id: "filtered" for item in combined if item.doc_id not in kept_ids}
        return OperatorExecutionResult(kept, drop_reasons=drops)


class GateExecutor(NamedExecutor):
    field_name, op_type = "router", "GATE"

    async def execute(self, spec: OperatorSpec, input_groups, context: ExecutionContext) -> OperatorExecutionResult:
        assert isinstance(spec, GateSpec)
        router = context.binding(spec.router, "GATE")
        fn = getattr(router, "route", router)
        route = await _call(fn, context.query, _documents(_combined(input_groups)))
        route = str(getattr(route, "route", route))
        if route not in spec.branches:
            raise OperatorConfigurationError(f"GATE {spec.op_id} selected undeclared route {route!r}")
        return OperatorExecutionResult(
            tuple(_documents(_combined(input_groups))),
            gate_values={"selected_route": route, "selected_operator_ids": spec.branches[route]},
        )


class BoostExecutor(NamedExecutor):
    field_name, op_type = "booster", "BOOST"


class ExpandExecutor(NamedExecutor):
    field_name, op_type = "expander", "EXPAND"


class TransformExecutor(NamedExecutor):
    field_name, op_type = "transformer", "TRANSFORM"


class GenerateExecutor(NamedExecutor):
    field_name, op_type = "generator", "GENERATE"


def default_operator_executors() -> dict[str, OperatorExecutor]:
    return {
        "SOURCE": SourceExecutor(),
        "FUSE": FuseExecutor(),
        "RERANK": RerankExecutor(),
        "FILTER": FilterExecutor(),
        "GATE": GateExecutor(),
        "BOOST": BoostExecutor(),
        "EXPAND": ExpandExecutor(),
        "TRANSFORM": TransformExecutor(),
        "GENERATE": GenerateExecutor(),
    }

from __future__ import annotations

import asyncio
import time
import traceback
import uuid
from dataclasses import dataclass, field, replace
from typing import Any, Mapping, Sequence

from retrieval_observatory.config.operators import (
    FuseSpec,
    PipelineGraphSpec,
    RerankSpec,
    SourceSpec,
)
from retrieval_observatory.pipeline.executors import (
    ExecutionContext,
    OperatorConfigurationError,
    OperatorExecutionResult,
    OperatorExecutor,
    default_operator_executors,
)
from retrieval_observatory.tracing.candidates import build_candidate_transition
from retrieval_observatory.tracing.model import OperatorSpan, RetrievalTrace, TraceTiming, critical_path_latency_ms
from retrieval_observatory.types import Document, PipelineResult, Query, StageSnapshot


@dataclass
class DAGNode:
    """Deprecated construction value accepted only at the native Python boundary."""

    node_id: str
    op_type: str
    inputs: list[str] = field(default_factory=list)
    adapter: Any = None
    k: int = 10
    rrf_k: int = 60
    top_k: int = 100
    fetch_k: int = 100


@dataclass(frozen=True)
class _Execution:
    spec: Any
    result: OperatorExecutionResult
    transition: Any
    latency_ms: float
    error: str | None = None
    error_traceback: str | None = None


def _legacy_graph(pipeline_id: str, nodes: Sequence[DAGNode], output_id: str) -> tuple[PipelineGraphSpec, dict[str, Any]]:
    specs = []
    bindings: dict[str, Any] = {}
    for node in nodes:
        parents = tuple(node.inputs)
        if node.op_type == "SOURCE":
            name = f"{node.node_id}:adapter"
            bindings[name] = node.adapter
            specs.append(SourceSpec(node.node_id, parents, {"k": node.k}, adapter=name))
        elif node.op_type == "FUSE":
            specs.append(FuseSpec(node.node_id, parents, {"rrf_k": node.rrf_k}, top_k=node.top_k))
        elif node.op_type == "RERANK":
            name = f"{node.node_id}:adapter"
            bindings[name] = node.adapter
            specs.append(RerankSpec(node.node_id, parents, {"merge_policy": "concat"}, adapter=name, top_k=node.k))
        else:
            raise OperatorConfigurationError(
                f"Legacy DAGNode cannot express {node.op_type}; use an operator-specific PipelineGraphSpec"
            )
    return PipelineGraphSpec(pipeline_id, tuple(specs), (output_id,)), bindings


class DAGPipeline:
    """Execute validated operator specifications while preserving graph evidence."""

    def __init__(
        self,
        graph: PipelineGraphSpec | None = None,
        adapters: Mapping[str, Any] | None = None,
        executors: Mapping[str, OperatorExecutor] | None = None,
        *,
        pipeline_id: str | None = None,
        nodes: Sequence[DAGNode] | None = None,
        output_id: str | None = None,
        service_id: str = "retobs",
    ):
        if graph is None:
            if pipeline_id is None or nodes is None or output_id is None:
                raise TypeError("DAGPipeline requires graph or pipeline_id/nodes/output_id")
            graph, legacy_adapters = _legacy_graph(pipeline_id, nodes, output_id)
            adapters = {**legacy_adapters, **dict(adapters or {})}
        self.graph = graph
        self.pipeline_id = graph.pipeline_id
        self.service_id = service_id
        self.adapters = dict(adapters or {})
        self.executors = dict(executors or default_operator_executors())
        self.nodes = {item.op_id: item for item in graph.operators}
        self.output_id = graph.final_operator_ids[0] if len(graph.final_operator_ids) == 1 else ""
        self._order = self._topological_order()
        self._order_index = {op_id: index for index, op_id in enumerate(self._order)}
        self._waves = self._execution_waves()
        self._validate_bindings()

    def _validate_bindings(self) -> None:
        for spec in self.graph.operators:
            if spec.op_type not in self.executors:
                raise OperatorConfigurationError(f"No {spec.op_type} executor registered for {spec.op_id}")
            field = {
                "SOURCE": "adapter", "RERANK": "adapter", "FILTER": "predicate", "GATE": "router",
                "BOOST": "booster", "EXPAND": "expander", "TRANSFORM": "transformer", "GENERATE": "generator",
            }.get(spec.op_type)
            if field and getattr(spec, field) not in self.adapters:
                raise OperatorConfigurationError(f"No {spec.op_type} executor registered for {spec.op_id}")

    def _topological_order(self) -> list[str]:
        declared = [item.op_id for item in self.graph.operators]
        known = set(declared)
        indegree = {item.op_id: len(item.parents) for item in self.graph.operators}
        children = {op_id: [] for op_id in declared}
        for item in self.graph.operators:
            for parent in item.parents:
                if parent not in known:
                    raise ValueError(f"DAG node '{item.op_id}' has unknown input '{parent}'")
                children[parent].append(item.op_id)
        ready = [op_id for op_id in declared if indegree[op_id] == 0]
        result: list[str] = []
        while ready:
            current = ready.pop(0)
            result.append(current)
            for child in children[current]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    ready.append(child)
            ready.sort(key=declared.index)
        if len(result) != len(declared):
            raise ValueError("DAG contains a cycle")
        return result

    def _execution_waves(self) -> list[list[str]]:
        depth: dict[str, int] = {}
        for op_id in self._order:
            parents = self.nodes[op_id].parents
            depth[op_id] = 0 if not parents else 1 + max(depth[parent] for parent in parents)
        return [[op_id for op_id in self._order if depth[op_id] == value] for value in sorted(set(depth.values()))]

    async def _execute(
        self, spec: Any, query: Query, candidates: Mapping[str, tuple[Any, ...]]
    ) -> _Execution:
        groups = {parent: candidates.get(parent, ()) for parent in spec.parents}
        started = time.perf_counter()
        try:
            executor = self.executors[spec.op_type]
            result = await executor.execute(spec, groups, ExecutionContext(query, self.adapters))
            transition = build_candidate_transition(
                input_groups=groups,
                output_items=result.outputs,
                op_id=spec.op_id,
                op_type=spec.op_type,
                decision_reasons=result.drop_reasons,
            )
            return _Execution(spec, result, transition, (time.perf_counter() - started) * 1000)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            transition = build_candidate_transition(
                input_groups=groups, output_items=(), op_id=spec.op_id, op_type=spec.op_type
            )
            return _Execution(
                spec, OperatorExecutionResult((), status="ERROR"), transition,
                (time.perf_counter() - started) * 1000, str(exc), traceback.format_exc(),
            )

    def _span(self, execution: _Execution) -> OperatorSpan:
        input_groups = {
            parent: tuple(
                replace(candidate, drop_reason=execution.result.drop_reasons.get(candidate.doc_id, candidate.drop_reason))
                for candidate in candidates
            )
            for parent, candidates in execution.transition.input_groups.items()
        }
        return OperatorSpan(
            op_id=execution.spec.op_id,
            op_type=execution.spec.op_type,
            op_name=execution.spec.op_id,
            parent_ids=tuple(execution.spec.parents),
            status="ERROR" if execution.error else execution.result.status,
            latency_ms=max(0.0, execution.latency_ms),
            input_groups=input_groups,
            outputs=execution.transition.outputs,
            params={**dict(execution.spec.params), **dict(execution.result.metadata)},
            gate_values=dict(execution.result.gate_values),
            error=execution.error,
            branch_id=execution.spec.params.get("branch_id"),
        )

    async def run(self, query: Query | str, *, query_id: str | None = None) -> PipelineResult:
        query = Query(str(query), query_id=query_id or "") if isinstance(query, str) else query
        if query_id is not None and query.query_id != query_id:
            query = replace(query, query_id=query_id)
        candidates: dict[str, tuple[Any, ...]] = {}
        spans: list[OperatorSpan] = []
        snapshots: list[StageSnapshot] = []
        gate_choices: dict[str, tuple[str, tuple[str, ...]]] = {}
        started = time.perf_counter()
        active: list[str] = []

        def result(status: str, error: str | None = None) -> PipelineResult:
            wall = (time.perf_counter() - started) * 1000
            finals = tuple(
                op_id for op_id in self.graph.final_operator_ids
                if any(span.op_id == op_id and span.status == "FIRED" for span in spans)
            ) if status == "OK" else ()
            trace = RetrievalTrace(
                trace_id=uuid.uuid4().hex, service_id=self.service_id, run_id=None,
                query_id=query.query_id, query_text=query.text, pipeline_id=self.pipeline_id,
                spans=tuple(spans), final_op_ids=finals, status=status,
                timing=TraceTiming(wall, critical_path_latency_ms(spans), sum(span.latency_ms for span in spans)),
                metadata=dict(query.metadata), error_traceback=error,
            )
            return PipelineResult(query.query_id, self.pipeline_id, snapshots, wall, status, error, trace=trace)

        try:
            for wave in self._waves:
                active = list(wave)
                pending = []
                for op_id in wave:
                    spec = self.nodes[op_id]
                    skipped_by = next(
                        (
                            (gate_id, route) for gate_id, (route, selected) in gate_choices.items()
                            if op_id in {item for branches in self.nodes[gate_id].branches.values() for item in branches}
                            and op_id not in selected
                        ),
                        None,
                    )
                    if skipped_by:
                        gate_id, route = skipped_by
                        transition = build_candidate_transition(
                            input_groups={}, output_items=(), op_id=op_id, op_type=spec.op_type
                        )
                        pending.append(asyncio.sleep(0, result=_Execution(
                            spec,
                            OperatorExecutionResult(
                                (), status="SKIPPED_BY_GATE",
                                gate_values={"gate_op_id": gate_id, "selected_route": route},
                            ),
                            transition, 0.0,
                        )))
                    else:
                        pending.append(self._execute(spec, query, candidates))
                executions = list(await asyncio.gather(*pending))
                active = []
                errors = []
                for execution in executions:
                    span = self._span(execution)
                    spans.append(span)
                    if execution.error:
                        errors.append(execution.error_traceback or execution.error)
                        continue
                    candidates[execution.spec.op_id] = execution.transition.outputs
                    if execution.spec.op_type == "GATE" and span.status == "FIRED":
                        route = str(span.gate_values["selected_route"])
                        gate_choices[execution.spec.op_id] = (route, tuple(execution.spec.branches[route]))
                    if span.status == "FIRED":
                        docs = [
                            Document(
                                id=item.doc_id, text=str(item.metadata.get("text", "")), score=item.score,
                                rank=item.output_rank or item.rank, metadata=dict(item.metadata),
                            ) for item in span.outputs
                        ]
                        snapshots.append(StageSnapshot(
                            self._order_index[execution.spec.op_id], execution.spec.op_id, docs,
                            execution.latency_ms, candidate_count=len(docs), op_type=execution.spec.op_type,
                        ))
                if errors:
                    return result("ERROR", "\n".join(errors))
            return result("OK")
        except asyncio.CancelledError:
            elapsed = (time.perf_counter() - started) * 1000
            seen = {span.op_id for span in spans}
            for op_id in active:
                if op_id in seen:
                    continue
                spec = self.nodes[op_id]
                groups = {parent: candidates.get(parent, ()) for parent in spec.parents}
                spans.append(OperatorSpan(
                    op_id, spec.op_type, op_id, tuple(spec.parents), "TIMEOUT", elapsed,
                    input_groups=groups, error="Pipeline execution cancelled or timed out",
                ))
            return result("TIMEOUT", "Pipeline execution cancelled or timed out")


DagPipeline = DAGPipeline

