def __post_init__(self) -> None:
    # The lane-agreement test below is exact arithmetic, not a tuned threshold — but the
    # arithmetic only holds while a two-lane score cannot be reached by one lane alone.
    # Fail loudly rather than let a future settings change quietly turn a proof into a guess.
    if self.lane_depth > self.rrf_k + 1:
        raise ValueError(
            f"lane_depth={self.lane_depth} breaks the lane-agreement proof: with "
            f"rrf_k={self.rrf_k} a single lane can score up to {1 / (self.rrf_k + 1):.6f} "
            f"while two lanes can score as little as {2 / (self.rrf_k + self.lane_depth):.6f}. "
            f"Keep lane_depth <= {self.rrf_k + 1}."
        )

@property
def agreement_threshold(self) -> float:
    """A fused score above this proves the document was found by *both* lanes.

    A document found by one lane alone scores at most ``1 / (rrf_k + 1)``. A document
    found by both scores at least ``2 / (rrf_k + lane_depth)``, which the constructor
    guarantees is strictly larger. So the comparison is a proof, not a heuristic.
    """
