"""Word-overlap scoring over passages (Okapi BM25, written in-house)."""
from __future__ import annotations

import math
import re
from collections import Counter

from acmesearch.chunking import Passage

_WORD = re.compile(r"[a-z0-9']+")

K1 = 1.4
B = 0.75


def tokenize(text: str) -> list[str]:
    return _WORD.findall(text.lower())


class WordOverlapIndex:
    """In-memory sparse index. Rebuilt on start-up; the corpus is small enough."""

    def __init__(self, passages: list[Passage]):
        self.passages = passages
        self._docs = [tokenize(f"{p.heading} {p.body}") for p in passages]
        self._lengths = [len(d) for d in self._docs]
        self._avg_len = (sum(self._lengths) / len(self._lengths)) if self._lengths else 0.0
        self._postings: dict[str, list[tuple[int, int]]] = {}
        for position, doc in enumerate(self._docs):
            for term, count in Counter(doc).items():
                self._postings.setdefault(term, []).append((position, count))
        self._n = len(self._docs)

    def _idf(self, term: str) -> float:
        df = len(self._postings.get(term, ()))
        if df == 0:
            return 0.0
        return math.log(1 + (self._n - df + 0.5) / (df + 0.5))

    def top(self, question: str, limit: int) -> list[tuple[Passage, float]]:
        scores: dict[int, float] = {}
        for term in tokenize(question):
            idf = self._idf(term)
            if idf == 0.0:
                continue
            for position, count in self._postings[term]:
                length = self._lengths[position]
                denominator = count + K1 * (1 - B + B * length / (self._avg_len or 1))
                scores[position] = scores.get(position, 0.0) + idf * count * (K1 + 1) / denominator
        ordered = sorted(scores.items(), key=lambda item: (-item[1], item[0]))[:limit]
        return [(self.passages[position], score) for position, score in ordered]

