"""Second-pass scoring with a cross-encoder."""
from __future__ import annotations

from acmesearch.chunking import Passage

RERANK_MODEL = "cross-encoder/ms-marco-MiniLM-L-6-v2"


class PassageScorer:
    def __init__(self, model_name: str = RERANK_MODEL):
        from sentence_transformers import CrossEncoder

        self.model_name = model_name
        self._model = CrossEncoder(model_name)

    def score(self, question: str, passages: list[Passage]) -> list[tuple[Passage, float]]:
        if not passages:
            return []
        pairs = [[question, f"{p.heading}. {p.body}"] for p in passages]
        scores = self._model.predict(pairs, show_progress_bar=False).tolist()
        return sorted(zip(passages, scores), key=lambda item: -item[1])

